-- LOCAL QA ONLY. No claims of real provider participation. Roll back by default.
\set ON_ERROR_STOP on
begin;
do $$begin if current_database() not like 'production_catalog_%' then raise exception 'Disposable database required';end if;end;$$;
create temporary table net(k text primary key,id uuid default gen_random_uuid(),v jsonb);
insert into net(k) values('admin'),('provider'),('editor'),('other'),('patient'),('support'),('document');
insert into auth.users(id,email) select id,'network-'||k||'@qa.invalid' from net where k<>'document';
insert into public.staff_roles(user_id,role) select id,case k when 'admin' then 'super_admin' else 'support_agent' end from net where k in ('admin','support');
grant all on net to authenticated;grant select on net to anon;
create function pg_temp.n_assert(ok boolean,msg text) returns void language plpgsql as $$begin if ok is distinct from true then raise exception 'FAIL: %',msg;end if;raise notice 'PASS: %',msg;end;$$;
create function pg_temp.n_denied(stmt text,code text) returns void language plpgsql as $$begin begin execute stmt;exception when others then if position(code in sqlerrm)>0 then raise notice 'PASS: denied %',code;return;end if;raise;end;raise exception 'FAIL: operation permitted';end;$$;
create function pg_temp.n_input(extra jsonb default '{}') returns jsonb language sql as $$select jsonb_build_object('organizationId',(select id from net where k='org'),'operationId',gen_random_uuid(),'confirmed',true)||extra;$$;
create function pg_temp.n_case(extra jsonb default '{}') returns jsonb language sql as $$select jsonb_build_object('caseId',(select id from net where k='case'),'operationId',gen_random_uuid())||extra;$$;
\ir pg-catalog-reference-fixtures.sql
select pg_temp.qa_publish_references((select id from net where k='admin'));
insert into net(k,v) select 'baseline_hospitals',to_jsonb(count(*)) from public.hospitals where private.catalog_public_visible('hospital',id);
\ir pg-network-reference-fixtures.sql
insert into net(k,v) values('reference',pg_temp.qa_network_reference((select id from net where k='admin'))),('unrelated_reference',pg_temp.qa_network_reference((select id from net where k='admin')));
insert into net(k,id) select 'hospital',(v->>'hospitalId')::uuid from net where k='reference';
select pg_temp.n_assert(private.provider_connectivity('hospital',(select (v->>'hospitalId')::uuid from net where k='unrelated_reference'))='no_owner','reference-only listing has an executable honest no-owner Support state');
set local role authenticated;
select set_config('request.jwt.claim.sub',(select id::text from net where k='provider'),true);
insert into net(k,id) select 'org',(public.portal_command('create_organization','{"name":"LOCAL NETWORK Provider","providerType":"hospital","sourceKind":"first_party"}')->>'id')::uuid;
select pg_temp.n_assert(public.portal_network_readiness((select id from net where k='org'))->'rows'->0->>'verificationStatus'='not_submitted','registration grants a draft workspace, not authority');
select pg_temp.n_assert(public.inquiry_target('hospital',(select id from net where k='hospital'))->>'organizationId' is null,'published reference has no invented operational owner');
select pg_temp.n_denied(format('select public.portal_network_command(''assign_listing_ownership'',%L)',pg_temp.n_input(jsonb_build_object('entityKind','hospital','entityId',(select id from net where k='hospital'),'reason','Unrelated self-claim.'))::text),'PORTAL_DENIED');
select pg_temp.n_denied(format('select public.portal_network_command(''review_organization_verification'',%L)',pg_temp.n_input(jsonb_build_object('requestId',gen_random_uuid(),'status','approved','reason','Self-approval must fail.'))::text),'PORTAL_DENIED');
insert into net(k,id) select 'draft',(public.portal_command('save_record',jsonb_build_object('organizationId',(select id from net where k='org'),'kind','organization','name','LOCAL NETWORK Draft','data',jsonb_build_object('cityId',(select id from public.cities where slug='mumbai'),'description','Local private draft.','email','authority@qa.invalid','phone','00000000')))->>'id')::uuid;
reset role;
insert into storage.objects(bucket_id,name) select 'provider-documents',(select id::text from net where k='org')||'/'||id::text from net where k='document';
set local role authenticated;
select public.portal_command('register_document',jsonb_build_object('organizationId',(select id from net where k='org'),'documentId',(select id from net where k='document'),'name','LOCAL NETWORK authority.pdf','documentType','supporting_evidence','storagePath',(select id::text from net where k='org')||'/'||(select id::text from net where k='document'),'mimeType','application/pdf','sizeBytes',20));
insert into net(k,v) values('submit',pg_temp.n_input(jsonb_build_object('documentId',(select id from net where k='document'),'hospitalId',(select id from net where k='hospital'),'legalName','Local authorized organization','contactName','Local representative','contactEmail','authority@qa.invalid','contactPhone','00000000','declaration','Local QA declaration, no real organization represented.')));
insert into net(k,id) select 'request',(public.portal_network_command('submit_organization_verification',(select v from net where k='submit'))->>'requestId')::uuid;
select pg_temp.n_assert(public.portal_network_command('submit_organization_verification',(select v from net where k='submit'))->>'requestId'=(select id::text from net where k='request'),'submission retry returns same authority request');
select pg_temp.n_assert((select count(*)=1 from public.organization_verification_requests where organization_id=(select id from net where k='org')),'submission retry does not duplicate review requests');
select pg_temp.n_denied(format('select public.portal_network_command(''submit_organization_verification'',%L)',((select v from net where k='submit')||'{"legalName":"Changed retry"}')::text),'INQUIRY_RETRY_CONFLICT');
select set_config('request.jwt.claim.sub',(select id::text from net where k='support'),true);
select pg_temp.n_assert((select count(*)=0 from public.organization_verification_requests),'Support cannot read authority contact details or evidence');
select pg_temp.n_assert(public.portal_network_readiness((select id from net where k='org'))->'rows'->0->>'verificationStatus'='submitted','Support can read safe factual readiness');
select set_config('request.jwt.claim.sub',(select id::text from net where k='other'),true);
select pg_temp.n_assert((select count(*)=0 from public.organization_verification_requests),'another organization cannot read authority requests');
select pg_temp.n_denied(format('select public.portal_network_readiness(%L)',(select id from net where k='org')),'PORTAL_DENIED');
select set_config('request.jwt.claim.sub',(select id::text from net where k='admin'),true);
select public.portal_network_command('review_organization_verification',pg_temp.n_input(jsonb_build_object('requestId',(select id from net where k='request'),'status','changes_requested','reason','Local reviewer requests better authority clarification.')));
select set_config('request.jwt.claim.sub',(select id::text from net where k='provider'),true);
update net set id=(public.portal_network_command('submit_organization_verification',(select v from net where k='submit')||jsonb_build_object('operationId',gen_random_uuid(),'declaration','Local clarified authority declaration for isolated QA only.'))->>'requestId')::uuid where k='request';
select pg_temp.n_assert((select count(*)=2 from public.organization_verification_requests where organization_id=(select id from net where k='org')),'changes requested permits a new immutable review request and retains history');
select set_config('request.jwt.claim.sub',(select id::text from net where k='admin'),true);
insert into net(k,v) values('review',pg_temp.n_input(jsonb_build_object('requestId',(select id from net where k='request'),'status','approved','reason','Isolated QA authority review.','contactConfirmation','Local QA contact verification only.')));
select pg_temp.n_denied(format('select public.portal_network_command(''review_organization_verification'',%L)',(select v::text from net where k='review')),'PORTAL_EVIDENCE_REQUIRED');
select public.portal_command('review_document',jsonb_build_object('documentId',(select id from net where k='document'),'status','approved','message','Local private authority fixture reviewed.'));
select pg_temp.n_denied(format('select public.portal_network_command(''review_organization_verification'',%L)',((select v from net where k='review')-'contactConfirmation')::text),'PORTAL_CONTACT_CONFIRMATION_REQUIRED');
select pg_temp.n_denied(format('select public.portal_network_command(''review_organization_verification'',%L)',((select v from net where k='review')||'{"confirmed":false}')::text),'PORTAL_CONFIRMATION_REQUIRED');
select public.portal_network_command('review_organization_verification',(select v from net where k='review'));
select pg_temp.n_assert(public.inquiry_target('hospital',(select id from net where k='hospital'))->>'organizationId' is null,'authority approval alone does not connect or publish a listing');
select pg_temp.n_denied(format('select public.portal_network_command(''assign_listing_ownership'',%L)',pg_temp.n_input(jsonb_build_object('entityKind','hospital','entityId',(select (v->>'hospitalId')::uuid from net where k='unrelated_reference'),'reason','Unrelated scope must fail.'))::text),'PORTAL_OWNERSHIP_SCOPE');
select public.portal_network_command('assign_listing_ownership',pg_temp.n_input(jsonb_build_object('entityKind','hospital','entityId',(select id from net where k='hospital'),'recordId',(select id from net where k='draft'),'reason','Assign exact reviewed canonical hospital.')));
select public.portal_network_command('assign_listing_ownership',pg_temp.n_input(jsonb_build_object('entityKind','doctor','entityId',(select (v->>'doctorId')::uuid from net where k='reference'),'reason','Scoped local affiliated doctor.')));
select public.portal_network_command('assign_listing_ownership',pg_temp.n_input(jsonb_build_object('entityKind','package','entityId',(select (v->>'packageId')::uuid from net where k='reference'),'reason','Scoped local hospital package.')));
reset role;
\ir pg-network-authority-fixtures.sql
set local role authenticated;
select set_config('request.jwt.claim.sub',(select id::text from net where k='other'),true);
insert into net(k,id) select 'competing_org',(public.portal_command('create_organization','{"name":"LOCAL competing claimant","providerType":"hospital","sourceKind":"first_party"}')->>'id')::uuid;
reset role;
select pg_temp.qa_approve_authority((select id from net where k='competing_org'),(select id from net where k='other'),(select id from net where k='admin'),(select id from net where k='hospital'));
set local role authenticated;
select set_config('request.jwt.claim.sub',(select id::text from net where k='admin'),true);
select pg_temp.n_denied(format('select public.portal_network_command(''assign_listing_ownership'',%L)',pg_temp.n_input(jsonb_build_object('organizationId',(select id from net where k='competing_org'),'entityKind','hospital','entityId',(select id from net where k='hospital'),'reason','Competing claim must not silently transfer.'))::text),'PORTAL_OWNERSHIP_CONFLICT');
