select pg_temp.n_denied(format('select public.portal_publication_command(''publish_submission'',%L)',jsonb_build_object('submissionId',(select id from net where k='submission'))::text),'PORTAL_DENIED');
select set_config('request.jwt.claim.sub',(select id::text from net where k='admin'),true);
select public.portal_review_command('review_section',jsonb_build_object('submissionId',(select id from net where k='submission'),'recordId',(select id from net where k='draft'),'expectedRevision',1,'status','approved'));
select public.portal_command('review_field',jsonb_build_object('submissionId',(select id from net where k='submission'),'recordId',(select id from net where k='draft'),'field','name','status','verified','documentId',(select id from net where k='document'),'evidence','Local exact canonical identity evidence only.'));
select public.portal_command('review_submission',jsonb_build_object('submissionId',(select id from net where k='submission'),'status','approved'));
